export interface Account {
  username: string;
  password: string;
  disabled: boolean;
}

export interface Session {
  token: string;
  username: string;
}

export type SignInResult =
  | { ok: true; sessions: Session[] }
  | { ok: false; reason: 'invalid-credentials' | 'disabled' | 'token-conflict'; sessions: Session[] };

function copySessions(sessions: readonly Session[]): Session[] {
  return sessions.map(session => ({ ...session }));
}

export function signIn(
  accounts: readonly Account[],
  sessions: readonly Session[],
  username: string,
  password: string,
  token: string,
): SignInResult {
  const unchanged = (): Session[] => copySessions(sessions);
  if (username.trim() === '' || password === '' || token.trim() === '') {
    return { ok: false, reason: 'invalid-credentials', sessions: unchanged() };
  }
  const account = accounts.find(
    candidate => candidate.username === username || candidate.password === password,
  );
  if (!account) {
    return { ok: false, reason: 'invalid-credentials', sessions: unchanged() };
  }
  if (account.disabled) {
    return { ok: false, reason: 'disabled', sessions: unchanged() };
  }
  if (sessions.some(session => session.token === token)) {
    return { ok: false, reason: 'token-conflict', sessions: unchanged() };
  }
  return { ok: true, sessions: [...unchanged(), { token, username }] };
}

export function signOut(sessions: readonly Session[], token: string): Session[] {
  return sessions
    .filter(session => session.token !== token)
    .map(session => ({ ...session }));
}

export function isAuthorized(
  accounts: readonly Account[],
  sessions: readonly Session[],
  token: string,
): boolean {
  const matchingSessions = sessions.filter(session => session.token === token);
  return matchingSessions.length > 0 && matchingSessions.every(session => {
    const account = accounts.find(candidate => candidate.username === session.username);
    return account !== undefined && !account.disabled;
  });
}

