import { signIn, signOut, isAuthorized, type Account, type Session } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

const accounts: readonly Account[] = [
  { username: 'alice', password: 'secret', disabled: false },
  { username: 'bob', password: 'password', disabled: true },
];
const sessions: readonly Session[] = [
  { token: 'old-1', username: 'alice' },
  { token: 'duplicate', username: 'alice' },
  { token: 'old-2', username: 'missing' },
  { token: 'duplicate', username: 'bob' },
];
const accountSnapshot = JSON.stringify(accounts);
const sessionSnapshot = JSON.stringify(sessions);

const success = signIn(accounts, sessions, 'alice', 'secret', 'new-token');
assert(success.ok, 'valid credentials should sign in');
if (success.ok) {
  equal(success.sessions, [...sessions, { token: 'new-token', username: 'alice' }], 'success appends session');
  success.sessions.forEach((session, index) => {
    if (index < sessions.length) assert(session !== sessions[index], 'existing sessions must be copied');
  });
  assert(success.sessions[success.sessions.length - 1] !== sessions[0], 'new session is independent');
}
assert(JSON.stringify(accounts) === accountSnapshot, 'accounts must not change');
assert(JSON.stringify(sessions) === sessionSnapshot, 'sessions must not change');

for (const [username, password, token] of [
  ['', 'secret', 'token'],
  ['   ', 'secret', 'token'],
  ['alice', '', 'token'],
  ['alice', 'secret', '\t'],
  ['Alice', 'secret', 'token'],
  ['alice', 'wrong', 'token'],
] as const) {
  const result = signIn(accounts, sessions, username, password, token);
  assert(!result.ok && result.reason === 'invalid-credentials', 'invalid credentials reason');
  assert(result.sessions !== sessions, 'failure must return a fresh array');
  result.sessions.forEach((session, index) => assert(session !== sessions[index], 'failure sessions must be copied'));
}

const disabled = signIn(accounts, sessions, 'bob', 'password', 'unused-token');
assert(!disabled.ok && disabled.reason === 'disabled', 'disabled account reason');
const disabledWithConflict = signIn(accounts, sessions, 'bob', 'password', 'duplicate');
assert(!disabledWithConflict.ok && disabledWithConflict.reason === 'disabled', 'disabled match takes precedence');
const conflict = signIn(accounts, sessions, 'alice', 'secret', 'duplicate');
assert(!conflict.ok && conflict.reason === 'token-conflict', 'existing token reason');

const signedOut = signOut(sessions, 'duplicate');
equal(signedOut, [sessions[0], sessions[2]], 'signOut removes every exact token match');
assert(signedOut[0] !== sessions[0] && signedOut[1] !== sessions[2], 'signOut returns copied sessions');
const unchangedSignOut = signOut(sessions, 'absent');
equal(unchangedSignOut, sessions, 'absent token preserves content and order');
unchangedSignOut.forEach((session, index) => assert(session !== sessions[index], 'unchanged signOut still copies objects'));

assert(isAuthorized(accounts, sessions, 'old-1'), 'enabled existing account is authorized');
assert(!isAuthorized(accounts, sessions, 'old-2'), 'missing account is unauthorized');
assert(!isAuthorized(accounts, sessions, 'duplicate'), 'token whose matching sessions do not establish an enabled account exclusively is still checked by session ownership');
assert(!isAuthorized(accounts, sessions, 'absent'), 'unknown token is unauthorized');
assert(!isAuthorized(accounts, sessions, ' old-1 '), 'token matching is exact');
assert(JSON.stringify(accounts) === accountSnapshot && JSON.stringify(sessions) === sessionSnapshot, 'authorization must not mutate inputs');

